/**
 * 负责流水线与 handler 共享的夜间状态及执行端口契约。
 * 输入为捕获的阶段操作、已付效果和 actor 查询；输出为有类型的贡献及原状态引用。
 * 机械、觉醒和原毒的内建生产者提交 sourced intent，源原体/因果信息只供运行时消费。
 * 旧原毒／机械／觉醒注入 effect/claim 保留接受宽度；其额外 kind/origin/getter 不被当作新协议读取。
 * 所有内建原毒（含受赠及学者加成）均有来源；此契约不查询 World 或提交库存。
 * 这些外部自定义注入仍保留明确 legacy 接受政策，不把同名字段视为 owned 来源。
 * 本族加成回执记录不属于通用字段，按本夜状态身份由学者／导师唯一所有者保存。
 */
import { StatusMarksComponent } from "../../../../core/domain/components/status_marks";
import {
  ActionProvider,
  ActionRequest,
  ActionRequestExtras,
  ActionStage,
  EntityId,
  GameEvent,
  ExileFeedback,
  NightSummary,
  Role,
} from "../../../../core/domain/model";
import { World } from "../../../../core/domain/world";
import { ToolGateway } from "../../../gateway/tool_gateway";
import type { RoleCatalog } from "../../roles/catalog";
import type { DreamNightLink } from "../../roles/dreamer/night_frame";
import type { NightAbilityActorQuery } from "../../roles/night-ability-actors";
import type { AliveComponent } from "../../../../core/domain/components/alive";
import type { NativeNightFailurePolicy } from "../../../../rulesets/native-night-failure-policy";
import type { NativeNightTargetPolicy } from "../../../../rulesets/native-night-target-policy";
import type { NativeNightEffects } from "../../../../rulesets/native-night-effects";

import type {
  NightPoisonClaim,
  NightInspectionAttack,
  NightFoxInspectionClaim,
  NightMechanicalEffect,
  NightGuardClaim,
  NightMerchantBacklash,
  NightBlackMarketBacklash,
  NightAwakenedEffect,
  NightMechanicalIntent,
  NightAwakenedIntent,
  NightOriginalPoisonIntent,
} from "../../../../core/domain/night_effects";

/** 狼刀选定时捕获的原生命及印记引用；目标序号相同不代表原体和生命版本仍有效。 */
export interface WolfKnifeTargetScope {
  targetId: EntityId;
  life: AliveComponent;
  version: number;
  marks: StatusMarksComponent;
}

/**
 * 同一夜按阶段顺序累积的运行状态，流水线创建，具体 handler 写入所属效果。
 * 包含原组件、回执和当前性查询，不能直接序列化为玩家观察或录制格式。
 * 效果条目是运行提案或捕获记录；空容器存在不表示已付、有效或已标死，这些由各所有者分别核对。
 */
export interface NightStageState {
  /** 学者／导师在原冲突检查点产生的死亡与刀口；不是直接修改 Alive 的指令。 */
  modifierDeaths?: import("../../../../core/domain/night_effects").NightLifeScope[];
  modifierKnifeTargets?: EntityId[];
  wolfChatOrder: EntityId[];
  endedWolves: Set<EntityId>;
  wolfVotes: Record<number, number>;
  wolfTarget: EntityId | null;
  wolfTargetScope?: WolfKnifeTargetScope;
  /** 实际参与选定普通狼刀的投票者；票表的目标键不能代替投票者名单。 */
  wolfTargetVoters?: EntityId[];
  seerChecks: NightSummary["seerChecks"];
  /** 已捕获的摄梦关系保留施法者和目标原生命；保护与死亡闭包由同一梦实例推导。 */
  dreamLinks: DreamNightLink[];
  /** 内建有来源 intent 与旧注入 claim 共存；仅同名字段不能把旧对象变成内建来源。 */
  poisonClaims?: Array<NightOriginalPoisonIntent | NightPoisonClaim>;
  inspectionAttacks?: NightInspectionAttack[];
  retaliationAttacks?: import("../../../../core/domain/night_effects").NightRetaliationAttack[];
  nightImmunities?: import("../../../../core/domain/night_effects").NightImmunityClaim[];
  /** 恶夜骑士开夜时的原体绑定供付款后反射使用；含状态和回调，不是可公开的角色知识。 */
  evilKnightBindings?: Map<
    EntityId,
    NonNullable<ReturnType<typeof import("../../roles/evil_knight/state").captureEvilKnight>>
  >;
  foxInspections?: NightFoxInspectionClaim[];
  guardClaims?: NightGuardClaim[];
  merchantBacklashes?: NightMerchantBacklash[];
  blackMarketBacklashes?: NightBlackMarketBacklash[];
  /** 机械效果按护盾、攻击、失败分别保留，消费次数和来源规则由具体能力控制。 */
  mechanicalEffects?: {
    shields: Array<NightMechanicalIntent<"mechanical-shield"> | NightMechanicalEffect>;
    attacks: Array<NightMechanicalIntent<"mechanical-attack"> | NightMechanicalEffect>;
    failures: Array<NightMechanicalIntent<"mechanical-failure"> | NightMechanicalEffect>;
  };
  /** 觉醒效果与机械效果分列，不能因形状相近而合并付款或退休政策。 */
  awakenedEffects?: {
    shields: Array<NightAwakenedIntent<"awakened-shield"> | NightAwakenedEffect>;
    attacks: Array<NightAwakenedIntent<"awakened-attack"> | NightAwakenedEffect>;
  };
}

/**
 * 阶段 handler 使用的运行端口：请求、候选查询和效果写入均在当前阶段执行。
 * 异步行动返回后仍需检查 isCurrent 及具体原体许可；持有此上下文不自动获得领域提交权限。
 */
export interface NightStageContext {
  isCurrent(): boolean;
  readonly previousExile: Readonly<ExileFeedback> | null;
  world: World;
  roleCatalog: RoleCatalog;
  readonly nightActors: NightAbilityActorQuery;
  readonly nativeNightFailure: NativeNightFailurePolicy;
  readonly nativeNightTargets: NativeNightTargetPolicy;
  readonly nativeNightEffects: NativeNightEffects;
  toolGateway: ToolGateway;
  events: GameEvent[];
  actionProvider: ActionProvider;
  currentDay(): number;
  makeRequest(
    actorId: EntityId,
    allowedTools: ActionRequest["allowedTools"],
    context: ActionRequestExtras & { stage: ActionStage; requiresAction?: boolean },
  ): ActionRequest;
  getAliveByRole(role: Role): EntityId[];
  ensureMarks(entityId: EntityId): StatusMarksComponent;
  pickMajorityTarget(votes: Record<number, number>): EntityId | null;
  /** 迷雾有限板在所有投票者明确放弃后使用的回退，随机流具名且可复现。 */
  pickMistKnife?(ids: readonly EntityId[]): EntityId | null;
  shuffleWolves(ids: EntityId[]): EntityId[];
  state: NightStageState;
}

/** 默认收集器按原 priority 装配，流水线按计划原顺序执行；处理器返回不等于效果已造成实际死亡。 */
export interface NightStageHandler {
  id: string;
  priority: number;
  execute(ctx: NightStageContext): Promise<void>;
}

/**
 * Owns Evil Knight board roster bindings and its native-frame setup stage. Inputs are original
 * players and installed ability identities; outputs are current-roster checks and the registered
 * frame stage. It never rebuilds the roster after native actor replacement; stale bindings fail.
 */
import type { World } from "../../../../core/domain/world";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Camp, Role } from "../../../../core/domain/identity";
import { captureNightLife } from "../../../../core/domain/night_effects";
import type { NightStageHandler } from "../../stages/night/contracts";
import { captureEvilKnight } from "./state";
import type { NightAbilityReadView } from "../abilities";
type AbilityAuthority = {
  ability: NightAbilityReadView;
  state: NightAbilityReadView["state"];
  source: NightAbilityReadView["source"];
  identity: string;
};
function abilityIdentity(ability: NightAbilityReadView): string {
  const state = ability.state as unknown as Record<string, unknown>;
  return JSON.stringify([
    ability.id,
    ability.kind,
    ability.activation,
    ability.source,
    ability.sourceDisclosed,
    ability.startsOnDay,
    ability.expiresAfterDay,
    ability.maxUses,
    state.targetPolicy,
    state.actionPolicy,
    state.selfHealRule,
    state.knifeVisibility,
    state.potionPolicy,
    state.repeatPolicy,
    state.policy,
    state.inspectionPolicy,
    state.protectionPolicy,
  ]);
}
type RosterBinding = {
  id: number;
  role: RoleComponent;
  kind: Role;
  camp: Camp;
  state: RoleComponent["privateState"];
  refs: [string, unknown][];
  abilityRefs: [string, unknown][];
  authorities: AbilityAuthority[];
};
const installed = new WeakMap<World, RosterBinding[]>();
export function installEvilKnightBoard(world: World): void {
  if (installed.has(world)) throw new Error("evil_knight_board_reinstall");
  installed.set(
    world,
    world.entityIds().map((id) => {
      const role = world.getComponent(id, COMPONENT.Role);
      if (!role) throw new Error("evil_knight_roster_missing");
      return {
        id,
        role,
        kind: role.role,
        camp: role.camp,
        state: role.privateState,
        refs: Object.entries(role.privateState),
        abilityRefs: Object.entries(
          (role.privateState as { readonly abilities?: unknown }).abilities ?? {},
        ),
        authorities: Object.values(
          ((role.privateState as { readonly abilities?: unknown }).abilities ?? {}) as Record<
            string,
            NightAbilityReadView
          >,
        ).map((ability) => ({
          ability,
          state: ability.state,
          source: ability.source,
          identity: abilityIdentity(ability),
        })),
      };
    }),
  );
}
export function isEvilKnightBoard(world: World): boolean {
  return installed.has(world);
}
export function assertEvilKnightRosterCurrent(world: World): void {
  for (const entry of installed.get(world) ?? []) {
    if (
      world.getComponent(entry.id, COMPONENT.Role) !== entry.role ||
      entry.role.role !== entry.kind ||
      entry.role.camp !== entry.camp ||
      entry.role.privateState !== entry.state ||
      entry.refs.some(
        ([key, value]) => (entry.state as Readonly<Record<string, unknown>>)[key] !== value,
      ) ||
      entry.authorities.some(
        (a) =>
          a.ability.state !== a.state ||
          a.ability.source !== a.source ||
          abilityIdentity(a.ability) !== a.identity,
      ) ||
      Object.keys((entry.state as { readonly abilities?: unknown }).abilities ?? {}).length !==
        entry.abilityRefs.length ||
      entry.abilityRefs.some(
        ([key, value]) =>
          (
            (entry.state as { readonly abilities?: unknown }).abilities as
              Record<string, unknown> | undefined
          )?.[key] !== value,
      )
    )
      throw new Error("evil_knight_roster_revoked");
  }
}
export function assertEvilKnightNativeActor(world: World, actorId: number, expected: Role): void {
  if (!isEvilKnightBoard(world)) return;
  assertEvilKnightRosterCurrent(world);
  const role = world.getComponent(actorId, COMPONENT.Role);
  if (role?.role !== expected || role.camp !== Camp.Good)
    throw new Error("evil_knight_actor_identity_revoked");
}
export const EVIL_KNIGHT_FRAME_STAGE: NightStageHandler = {
  id: "evil_knight_frame",
  priority: 50,
  async execute(ctx) {
    if (!isEvilKnightBoard(ctx.world)) return;
    assertEvilKnightRosterCurrent(ctx.world);
    if (ctx.state.evilKnightBindings) throw new Error("evil_knight_night_reentry");
    const bindings = new Map<number, NonNullable<ReturnType<typeof captureEvilKnight>>>();
    for (const id of ctx.world.getAliveEntityIds()) {
      const life = captureNightLife(ctx.world, id);
      const binding = life && captureEvilKnight(ctx.world, life);
      if (binding) bindings.set(id, binding);
    }
    ctx.state.evilKnightBindings = bindings;
    ctx.state.nightImmunities = [...bindings.values()];
  },
};

/**
 * 负责恶灵骑士公开的只读普通狼刀目标贡献，并提供原状态读取、资格校验及反射提交入口。
 * 输入是绑定原 World 的目标序号，或具体原体／查验上下文；输出保留原存活角色允许结果，
 * 包括未安装专用板子时的原政策。查询错误原样传播，绑定不提前读组件或授予生命、反射写权。
 * 名单复验向夜间规则组合及阶段检查点公开原函数，不读写库存或开启行动窗口。
 * 资格与反射命令仍保留原来源校验、付款时点和 frame 写入；狼刀目标查询本身只读。
 * 反射终态与失败前缀由状态命令维护，出口不拦截错误或尝试回滚。
 */
import { Role, type EntityId } from "../../../../core/domain/identity";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { World } from "../../../../core/domain/world";
export { isEvilKnightBoard, assertEvilKnightNativeActor, assertEvilKnightRosterCurrent } from "./night_frame";
export { commitEvilKnightReflection } from "./state";

export interface EvilKnightKnifeTargetQuery {
  allows(targetId: EntityId): boolean;
}

export function bindEvilKnightKnifeTargetQuery(world: World): EvilKnightKnifeTargetQuery {
  return Object.freeze({
    allows: (targetId: EntityId) =>
      world.getComponent(targetId, COMPONENT.Role)?.role !== Role.EvilKnight,
  });
}

export { getEvilKnightState } from "./state";

/**
 * Binds original native paid effect commands and lazy sealed-controller loaders.
 * Inputs are the original stage context, readonly receipts/abilities and deferred
 * effect arguments; outputs retain paid prefixes, modifier facts and reflection.
 * Only this command binding restores the original receipt commit permission.
 * Context, World, events and source getters remain at their original call sites;
 * binding reads none of them and never adds eligibility, refunds or serialization.
 */
import { Role } from "../core/domain/identity";
import type { NightLifeScope } from "../core/domain/night_effects";
import type { NightStageContext } from "../game/mechanisms/stages/night/contracts";
import type { NightAbilityReadView } from "../game/mechanisms/roles/abilities";
import {
  isScholarMentorBoard,
  recordScholarMentorNativeTarget,
  scholarMentorKnifeEligible,
} from "../game/mechanisms/roles/scholar_mentor/ports";
import {
  isEvilKnightBoard,
  commitEvilKnightReflection,
} from "../game/mechanisms/roles/evil_knight/ports";
import {
  commitTimeConsortEffect,
  type TimeConsortReceipt,
} from "../game/mechanisms/roles/time_wolf_consort/ports";
import {
  loadDemonNativeNightController,
  loadDemonNativePotionController,
} from "../game/mechanisms/roles/demon_hunter/ports";
import type { NativeReflectedTarget } from "./native-night-target-policy";

export interface NativeNightEffects {
  commitReflectedTarget(
    receipt: NativeReflectedTarget | null,
    day: number,
    sourceId: number,
    kind: "check" | "guard" | "poison",
  ): void;
  recordModifierTarget(
    day: number,
    actorId: number,
    kind: "check" | "guard" | "poison",
    targetId: () => number | null,
  ): void;
  recordKnifeModifierTarget(targetId: () => number | null): void;
  commitNativeReflection(
    kind: "seer_check" | "poison",
    ability: NightAbilityReadView<"seer_check" | "potion">,
    targetId: number,
    source: () => NightLifeScope,
    isCurrent: () => boolean,
  ): void;
  loadSealedNightController: typeof loadDemonNativeNightController;
  loadSealedPotionController: typeof loadDemonNativePotionController;
}

/** The same context object is handed to the existing paid command, without a copy. */
export function bindNativeNightEffects(context: () => NightStageContext): NativeNightEffects {
  return Object.freeze({
    commitReflectedTarget(
      receipt: NativeReflectedTarget | null,
      day: number,
      sourceId: number,
      kind: "check" | "guard" | "poison",
    ) {
      commitTimeConsortEffect(context(), receipt as TimeConsortReceipt | null, day, sourceId, kind);
    },
    recordModifierTarget(
      day: number,
      actorId: number,
      kind: "check" | "guard" | "poison",
      targetId: () => number | null,
    ) {
      if (isScholarMentorBoard(context().world))
        recordScholarMentorNativeTarget(context().world, day, actorId, kind, targetId());
    },
    recordKnifeModifierTarget(targetId: () => number | null) {
      if (isScholarMentorBoard(context().world)) {
        const actor = context()
          .world.getAliveEntityIds()
          .find((id) => scholarMentorKnifeEligible(context().world, context().currentDay(), id));
        if (actor !== undefined)
          recordScholarMentorNativeTarget(
            context().world,
            context().currentDay(),
            actor,
            "kill",
            targetId(),
          );
      }
    },
    commitNativeReflection(
      kind: "seer_check" | "poison",
      ability: NightAbilityReadView<"seer_check" | "potion">,
      targetId: number,
      source: () => NightLifeScope,
      isCurrent: () => boolean,
    ) {
      if (isEvilKnightBoard(context().world)) {
        if (
          ability.source.kind !== "native" ||
          ability.source.role !== (kind === "seer_check" ? Role.Seer : Role.Witch)
        )
          throw new Error(
            kind === "seer_check"
              ? "evil_knight_seer_source_invalid"
              : "evil_knight_witch_source_invalid",
          );
        const reflection = commitEvilKnightReflection(
          context().world,
          context().state.evilKnightBindings?.get(targetId) ?? null,
          source(),
          kind,
          isCurrent,
        );
        if (reflection) (context().state.retaliationAttacks ??= []).push(reflection);
      }
    },
    loadSealedNightController: loadDemonNativeNightController,
    loadSealedPotionController: loadDemonNativePotionController,
  });
}

/**
 * 负责：顺序执行夜间阶段、收集有来源的效果并准备黎明伤害。
 * 输入：当前 World、真实 RulePlan、阶段贡献和行动提供者；输出：原夜间摘要与死亡提案。
 * 原生策略和具体生命周期单位由同一计划装配；actor、目标、库存和原体资格仍现场查询。
 * 默认阶段固定成员及顺序，注入惰性来源在前一阶段提交后才拉取下一项。
 * 取消检查后，参数仍在首次 acquired 的原 World 参数位置绑定；改变参数不隐式重编译。
 * 来源元数据不授予资格；原 handler receiver 与 execute getter 保持晚读取。
 * 已捕获 day 原值交给伤害折叠，机械／觉醒／原毒 intent 单独保留来源及原体；
 * intent 元数据不进入夜间摘要、事件或 schema2，旧注入 claim 保持兼容。
 * 晚交接保留真实单位的 owned 状态和原失败前缀，result 与最终伤害仍在原已付效果之后准备。
 * 已提交重入准入交有限规则组合，在原婚约开夜之后检查；拒绝不撤销原已付效果，原 finally 仍收尾。
 * 明辉／梦及增益的伤害输入组合归规则集；本流水线保原检查点，运行梦句柄不进入摘要或归档。
 */
import { attachNightUnit } from "../../../core/domain/night-unit";
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { prepareNightPipelineLifecycle, type NightLifecycleHandoff } from "../../../rulesets/night-lifecycle-plan";


import { assertNightSetupReady, assertNightReadable } from "../../../rulesets/night-readability";
import { RulePlan } from "../../../rulesets/rule-plan";
import { bindNightAbilityActorQuery } from "../../mechanisms/roles/night-ability-actors";
import { isFragrantPairBoard, fragrantAuthoritySnapshot } from "../../mechanisms/roles/fragrant_pair_seer/ports";
import { createNobleNightAbortReceiver, attachNobleNightReceiver, checkpointNobleBodyAuthority, isNobleBodyBoard } from "../../mechanisms/roles/noble_secret_body/ports";
import { animalAuthoritySnapshot } from "../../mechanisms/roles/animal_dream/ports";
import { isRadiantEclipseBoard } from "../../mechanisms/roles/radiant_eclipse/ports";
import { isScholarMentorBoard } from "../../mechanisms/roles/scholar_mentor/ports";
import { mistKnifeTargets, isMistRavenBoard } from "../../mechanisms/roles/mist_raven/ports";
import { assertScholarMentorBonusEffects } from "../../mechanisms/roles/scholar_mentor/night_stages";
import { isTimeConsortBoard } from "../../mechanisms/roles/time_wolf_consort/ports";
import { isMagicianBoard } from "../../mechanisms/roles/magician/ports";
import { isRedMoonBoard } from "../../mechanisms/roles/demon_hunter/ports";
import {
  isNightmareBoard,
} from "../../mechanisms/roles/nightmare_shadow/ports";
import {
  isEvilKnightBoard,
  assertEvilKnightRosterCurrent,
} from "../../mechanisms/roles/evil_knight/ports";
import {
  sealNativeGuardContribution,
  lateUnknownGuardContribution,
} from "../../mechanisms/roles/demon_hunter/guard_contribution";
import { demonHunterActorId, originalDemonNightLives, demonOriginalWolfSourceCurrent, demonOriginalWolfTargetCurrent } from "../../mechanisms/roles/demon_hunter/ports";
import { sealDeliveredDemonWitchSources } from "../../mechanisms/roles/demon_hunter/native_potion_controller";
import { weddingSetup } from "../../mechanisms/roles/ghost_bride/ports";
import { discardStaleWeddingKnife } from "../../mechanisms/roles/ghost_bride/night_stages";
import { COMPONENT } from "../../../core/domain/components/names";
import { RoleComponent } from "../../../core/domain/components/role";
import {
  StatusMarksComponent,
  statusMarkSnapshot,
} from "../../../core/domain/components/status_marks";
import {
  ActionProvider,
  ActionRequest,
  ActionRequestExtras,
  ActionStage,
  BoardConfig,
  EntityId,
  GameEvent,
  ExileFeedback,
  NightSummary,
  Phase,
  Role,
  TieBreakerStrategy,
  StatusMark,
  DeathCause,
} from "../../../core/domain/model";
import {
  DamageResolutionResult,
  DamageResolutionSystem,
} from "../../../core/domain/systems/damage_resolution_system";
import { World } from "../../../core/domain/world";
import { ToolGateway } from "../../gateway/tool_gateway";
